# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::LegacyAuditConversion do
  let(:legacy_audit_entry_row) { { "id" => 5, "company_id" => 1, "created_at" => Time.utc(2026, 1, 2, 3) } }

  def legacy_audit(**overrides)
    {
      id: 910, action: "update", associated_type: "Company", associated_id: 1, auditable_id: 5,
      user_type: "User", user_id: 42, username: nil,
      audited_changes: { "note" => ["old", "new"] }, created_at: Time.utc(2026, 2, 3, 4)
    }.merge(overrides)
  end

  it "converts create and update audits keeping company, author, action, original created_at and change values" do
    entry_created = Time.utc(2025, 3, 1, 9)
    create_at = Time.utc(2025, 3, 1, 9, 0, 1)
    update_at = Time.utc(2025, 3, 2, 10)
    entries_by_id = { 40 => { "id" => 40, "company_id" => 5, "created_at" => entry_created } }
    audits = [
      { id: 501, action: "create", associated_type: "Company", associated_id: 5, auditable_id: 40,
        user_type: "User", user_id: 11, username: nil,
        audited_changes: { "duration" => 60.0, "note" => "first" }, created_at: create_at },
      { id: 502, action: "update", associated_type: "Company", associated_id: 5, auditable_id: 40,
        user_type: "User", user_id: 12, username: nil,
        audited_changes: { "duration" => [60.0, 90.0], "note" => [nil, "second"] }, created_at: update_at }
    ]

    # "Keep its company, author, action, original `created_at` and change values (before and after from
    # `audited_changes`), and set `entry_created_at` from the entry."
    result = described_class.convert(audits:, entries_by_id:)

    expect(result[:refusals]).to be_empty
    created, updated = result[:rows].sort_by { |row| row["id"] }
    expect(created).to include(
      "id" => 501, "company_id" => 5, "entry_id" => 40, "actor_type" => "user", "actor_id" => 11,
      "action" => "create", "before" => nil, "after" => { "duration" => 60.0, "note" => "first" },
      "entry_created_at" => entry_created, "created_at" => create_at
    )
    expect(updated).to include(
      "id" => 502, "company_id" => 5, "entry_id" => 40, "actor_type" => "user", "actor_id" => 12,
      "action" => "update", "before" => { "duration" => 60.0, "note" => nil },
      "after" => { "duration" => 90.0, "note" => "second" },
      "entry_created_at" => entry_created, "created_at" => update_at
    )
  end

  it "converts audits of two companies each under its own company with author, timestamps and change values" do
    entry_created_a = Time.utc(2026, 1, 2, 9)
    entry_created_b = Time.utc(2026, 1, 3, 9)
    entries_by_id = {
      10 => { "id" => 10, "company_id" => 1, "created_at" => entry_created_a },
      20 => { "id" => 20, "company_id" => 2, "created_at" => entry_created_b }
    }
    audits = [
      { id: 501, action: "create", associated_type: "Company", associated_id: 1, auditable_id: 10,
        user_type: "User", user_id: 5, username: nil, audited_changes: { "duration" => 1.5 },
        created_at: Time.utc(2026, 1, 2, 9, 0, 1) },
      { id: 502, action: "update", associated_type: "Company", associated_id: 2, auditable_id: 20,
        user_type: "User", user_id: 6, username: nil, audited_changes: { "note" => ["old", "new"] },
        created_at: Time.utc(2026, 1, 4, 10) }
    ]

    result = described_class.convert(audits:, entries_by_id:)

    expect(result[:refusals]).to be_empty
    rows = result[:rows].index_by { |row| row["id"] }
    expect(rows.fetch(501)).to include(
      "company_id" => 1, "entry_id" => 10, "actor_type" => "user", "actor_id" => 5, "action" => "create",
      "before" => nil, "after" => { "duration" => 1.5 },
      "created_at" => Time.utc(2026, 1, 2, 9, 0, 1), "entry_created_at" => entry_created_a
    )
    expect(rows.fetch(502)).to include(
      "company_id" => 2, "entry_id" => 20, "actor_type" => "user", "actor_id" => 6, "action" => "update",
      "before" => { "note" => "old" }, "after" => { "note" => "new" },
      "created_at" => Time.utc(2026, 1, 4, 10), "entry_created_at" => entry_created_b
    )
  end

  it "refuses an audit whose associated company differs from its entry's company under the entry's company only" do
    audit = legacy_audit(id: 900, associated_id: 2)

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    # The audit history must not land in another company's audit trail.
    expect(result[:rows]).to be_empty
    expect(result[:refusals].keys).to eq([1])
    expect(result[:refusals].fetch(1).join("\n")).to include("900")
  end

  it "refuses a username-only audit rather than recording it as the anonymous system actor" do
    audit = legacy_audit(id: 901, user_type: nil, user_id: nil, username: "legacy-importer")

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    # "Keep its company, author, action, original `created_at` and change values (before and after from `audited_changes`), and set `entry_created_at` from the entry."
    expect(result[:rows]).to be_empty
    expect(result[:refusals].keys).to eq([1])
    message = result[:refusals].fetch(1).join("\n")
    expect(message).to include("901")
    expect(message).to include("legacy-importer")
  end

  it "gives an audit with no user and no username the system actor" do
    audit = legacy_audit(user_type: nil, user_id: nil, username: "")

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:refusals]).to be_empty
    expect(result[:rows].sole).to include("actor_type" => "system", "actor_id" => 0)
  end

  it "converts a destroy audit whose entry is present into the stored values before and an empty object after" do
    audit = legacy_audit(action: "destroy", audited_changes: { "duration" => 60.0, "note" => nil })

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:rows].sole).to include(
      "action" => "destroy", "before" => { "duration" => 60.0, "note" => nil }, "after" => {}
    )
  end

  it "refuses a destroy audit whose entry is missing rather than dropping it silently" do
    audit = legacy_audit(id: 902, action: "destroy", auditable_id: 99, audited_changes: { "duration" => 60.0 })

    # Issue: "Convert each `audits` row whose auditable type is `TimesheetEntry` into a
    # checkpoint audit row in the `audit_events` shape." A row for an entry the checkpoint
    # does not hold cannot load, so it must be refused, not dropped.
    result = described_class.convert(audits: [audit], entries_by_id: {})

    expect(result[:rows]).to be_empty
    expect(result[:refusals].fetch(1).join(" ")).to include("902")
  end

  it "refuses an audit that names no company under its entry's company" do
    audit = legacy_audit(associated_type: nil, associated_id: nil)

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:rows]).to be_empty
    expect(result[:refusals].fetch(1).join("\n")).to include("910", "no company")
  end

  it "refuses an audit whose author type is not User" do
    audit = legacy_audit(user_type: "Agent", user_id: 3)

    result = described_class.convert(audits: [audit], entries_by_id: { 5 => legacy_audit_entry_row })

    expect(result[:rows]).to be_empty
    expect(result[:refusals].fetch(1).join("\n")).to include("910", "Agent")
  end

  it "builds rows that fit the checkpoint's entry_audits shape" do
    audits = [
      legacy_audit(id: 1, action: "create", audited_changes: { "note" => "first" }),
      legacy_audit(id: 2),
      legacy_audit(id: 3, user_type: nil, user_id: nil)
    ]

    rows = described_class.convert(audits:, entries_by_id: { 5 => legacy_audit_entry_row })[:rows]
    tables = Timekeeping::Handoff::Checkpoint::TABLES.keys.index_with { [] }.merge("entry_audits" => rows)

    expect(rows.pluck("id")).to eq([1, 2, 3])
    expect { Timekeeping::Handoff::Checkpoint.check_shape!(tables) }.not_to raise_error
  end
end
